import{TenBase,fmt,svgEl}from'./ten-base.js';import{calculate}from'../twelve-math.js';
export default class TwelveMath extends TenBase{
 constructor(host,ctx){super(host,ctx);this.draw()}
 move(i,p){if(['inverse-sin','inverse-cos','inverse-tan','derivative-corner','aod-increasing'].includes(this.mode))this.v=Math.max(this.ctx.scene.controls[0].min,Math.min(this.ctx.scene.controls[0].max,p[0]));else if(this.mode==='derivative-chain')this.x=Math.max(-3,Math.min(3,p[0]));this.ctx.scene.controls.forEach((c,i)=>{let el=this.controls.querySelectorAll('input')[i];el.value=this[c.key];el.previousElementSibling.textContent=`${fmt(this[c.key])} ${c.unit}`})}
 draw(){const id=this.mode,v=this.v,a=calculate(id,v,this.x),S=(en,hi)=>this.say(en,hi),F=fmt,mark=(p,s)=>this.mark(p,s),rows=[];this.clear();const line=(p,q,c='shape',attrs={})=>this.line(p,q,c,attrs),path=(ps,c='shape',fill=false)=>this.path(ps,c,fill),label=(p,s)=>this.text(p,s),gold=(p,q)=>line(p,q,'gold',{'stroke-width':3});
 const heading=(en,hi)=>label([-8,5],S(en,hi));
 const curve=(f,cls='shape')=>{let run=[];for(let x=-8.4;x<=8.4;x+=.025){let y=f(x);if(Number.isFinite(y)&&Math.abs(y)<5.2){run.push([x,y])}else if(run.length){this.path(run,cls,false,{style:'fill:none'});run=[]}}if(run.length)this.path(run,cls,false,{style:'fill:none'})};
 const region=(f,g,lo,hi)=>{let ps=[];for(let i=0;i<=80;i++){let x=lo+(hi-lo)*i/80;ps.push([x,f(x)])}for(let i=80;i>=0;i--){let x=lo+(hi-lo)*i/80;ps.push([x,g(x)])}path(ps,'shape',true)};
 const matrix=(A,p,name)=>{label([p[0],p[1]+.8],name);A.forEach((r,i)=>r.forEach((x,j)=>label([p[0]+j*1.8,p[1]-i*1.25],F(x))));line([p[0]-.4,p[1]+.4],[p[0]-.4,p[1]-1.6]);line([p[0]+2.7,p[1]+.4],[p[0]+2.7,p[1]-1.6])};
 const vec=(p,q,name)=>{gold(p,q);let dx=q[0]-p[0],dy=q[1]-p[1],len=Math.hypot(dx,dy);if(len){let u=[dx/len,dy/len];path([[q[0]-.25*u[0]+.13*u[1],q[1]-.25*u[1]-.13*u[0]],q,[q[0]-.25*u[0]-.13*u[1],q[1]-.25*u[1]+.13*u[0]]],'gold')}mark(q,name)};
 const spatial=()=>{this.clear(false);const P=([x,y,z])=>[x-.55*y,z-.35*y];for(let [q,n]of[[[5,0,0],'X'],[[0,5,0],'Y'],[[0,0,5],'Z']]){line([0,0],P(q),'axis');label(P(q),n)}return P};
 if(id==='relation-mod'){this.clear(false);a.classes.forEach((group,i)=>{let x=-6+i*4;this.circle([x,0],1.65,'shape',{stroke:['#f3c573','#9ad8ff','#b3e1a6','#e2b9ff'][i]});label([x-1.4,2.2],S('Class','वर्ग')+' '+i);group.forEach((q,j)=>mark([x-.8+j*.8,0],q))});rows.push(`x R y ⇔ ${S('m divides (x−y)','(x−y), m से विभाज्य')}; m=${v}`,S('Reflexive ✓ · symmetric ✓ · transitive ✓','स्वतुल्य ✓ · सममित ✓ · संक्रामक ✓'))}
 else if(id==='relation-map'){this.clear(false);let X=a.input.map((x,i)=>[-5,3-i*1.4]),Y=a.codomain.map((y,i)=>[4,3-i*1.4]);X.forEach((p,i)=>{mark(p,a.input[i]);line(p,Y[a.codomain.indexOf(a.output[i])])});Y.forEach((p,i)=>mark(p,a.codomain[i]));label([-6,4.4],S('Domain A','प्रांत A'));label([2,4.4],S('Codomain B','सहप्रांत B'));rows.push(`f(x)=${['x','x²','0'][v]}`,S('One-one','एकैकी')+': '+S(a.one?'Yes':'No',a.one?'हाँ':'नहीं'),S('Onto','आच्छादक')+': '+S(a.onto?'Yes':'No',a.onto?'हाँ':'नहीं'))}
 else if(id==='relation-compose'){curve(x=>v*x*x+1);curve(x=>(v*x+1)**2,'gold');mark([this.x,a.fg],'f(g(x))');mark([this.x,a.gf],'g(f(x))');rows.push(`f(g(${F(this.x)}))=${F(a.fg)}; g(f(${F(this.x)}))=${F(a.gf)}`,v===0?S('f is constant: no inverse on R.','f अचर है: R पर प्रतिलोम नहीं।'):`f⁻¹(x)=(x−1)/${v}`,S('Green: f∘g; gold: g∘f.','हरा: f∘g; सुनहरा: g∘f।'))}
 else if(id.startsWith('inverse-')){curve(a.f);this.points=[[v,a.value]];this.point(this.points[0],0,'P');if(id==='inverse-tan'){line([-8,Math.PI/2],[8,Math.PI/2],'axis',{'stroke-dasharray':'5 5'});line([-8,-Math.PI/2],[8,-Math.PI/2],'axis',{'stroke-dasharray':'5 5'})}rows.push(`x=${F(v)}; ${id==='inverse-sin'?'sin':id==='inverse-cos'?'cos':'tan'}⁻¹(x)=${F(a.value)} rad`,S('Inverse function, not reciprocal. Drag the gold point or use arrows.','प्रतिलोम फलन है, व्युत्क्रम नहीं। सुनहरा बिंदु खींचें या तीर चलाएँ।'));if(id==='inverse-cos')rows.push(`sin⁻¹x+cos⁻¹x=${F(a.sum)} rad = π/2`)}
 else if(id.startsWith('matrix-')){this.clear(false);matrix(a.A,[-7,2],'A');if(id==='matrix-add'){matrix(a.B,[-2,2],'B');matrix(a.result,[3,2],`A+(${v})B`);rows.push('A+kB = '+JSON.stringify(a.result))}else if(id==='matrix-product'){matrix(a.B,[-2,2],'B');matrix(a.AB,[-7,-2],'AB');matrix(a.BA,[1,-2],'BA');rows.push('AB='+JSON.stringify(a.AB),'BA='+JSON.stringify(a.BA),v===0?'AB=BA':'AB≠BA')}else{matrix(a.result,[1,2],'Aᵀ');rows.push(S('Symmetric','सममित')+': '+S(a.symmetric?'Yes':'No',a.symmetric?'हाँ':'नहीं'),'Aᵀ = '+JSON.stringify(a.result))}}
 else if(id==='det-area'){path([[0,0],a.a,[2+v,4],a.b],'shape',true);vec([0,0],a.a,'a');vec([0,0],a.b,'b');rows.push(`det=2×3−1×(${v})=${a.det}`,S('Area','क्षेत्रफल')+`=|det|=${a.value} units²`,a.det===0?S('Collinear: area 0.','संरेख: क्षेत्रफल 0।'):S('Sign describes orientation; area is nonnegative.','चिह्न अभिविन्यास का है; क्षेत्रफल गैरऋणात्मक है।'))}
 else if(id==='det-inverse'){this.clear(false);matrix(a.A,[-6,2],'A');if(a.inverse)matrix(a.inverse,[1,2],'A⁻¹');else label([0,0],S('No inverse','प्रतिलोम नहीं'));rows.push(`det A = ${v}−2=${a.det}`,a.inverse?'A⁻¹='+JSON.stringify(a.inverse.map(r=>r.map(F))):S('Singular matrix: determinant 0.','अव्युत्क्रमणीय आव्यूह: सारणिक 0।'))}
 else if(id==='det-system'){this.equation(1,1,-3);this.equation(1,v,-4,'gold');if(a.point)mark(a.point,'P');rows.push(a.point?`x=${F(a.point[0])}, y=${F(a.point[1])}`:S('No solution: parallel distinct lines.','कोई हल नहीं: अलग समांतर रेखाएँ।'),`D=${v}−1=${a.value}`)}
 else if(id==='continuity-piece'){curve(x=>x+1);this.circle([0,1],.13,'shape',{style:'fill:#123c33'});mark([0,v],'f(0)');rows.push(`lim f(x), x→0 = 1; f(0)=${v}`,S(a.continuous?'Continuous at 0':'Discontinuous at 0',a.continuous?'0 पर सतत':'0 पर असतत'))}
 else if(id==='derivative-corner'){curve(Math.abs);this.points=[[v,a.value]];this.point(this.points[0],0,'P');if(a.slope!==null)curve(x=>a.value+a.slope*(x-v),'gold');rows.push(`f(${F(v)})=${F(a.value)}`,a.slope===null?S('At 0: left derivative −1, right derivative +1. Not differentiable.','0 पर बायाँ अवकलज −1, दायाँ +1। अवकलनीय नहीं।'):`f′(${F(v)})=${a.slope}`,S('Continuous everywhere.','हर वास्तविक बिंदु पर सतत।'))}
 else if(id==='derivative-chain'||id==='aod-increasing'){let f=id==='aod-increasing'?x=>x**3/3-x:x=>Math.sin(v*x);curve(f);curve(x=>a.point[1]+a.slope*(x-a.point[0]),'gold');this.points=[a.point];this.point(a.point,0,'P');rows.push(`f(${F(a.point[0])})=${F(a.value)}; f′=${F(a.slope)}`,S('Gold line: local tangent.','सुनहरी रेखा: स्थानीय स्पर्शरेखा।'));if(id==='aod-increasing')rows.push(S(a.slope>0?'Increasing here':a.slope<0?'Decreasing here':'Stationary here',a.slope>0?'यहाँ वर्धमान':a.slope<0?'यहाँ ह्रासमान':'यहाँ स्थिर बिंदु'))}
 else if(id==='aod-max'){this.clear(false);let L=v*.65,W=a.width*.65;path([[-4,-2],[-4+L,-2],[-4+L,-2+W],[-4,-2+W]],'shape',true);label([-4+L/2,-2.5],`x=${F(v)}`);label([-4.8,-2+W/2],F(a.width));rows.push(`A=${F(v)}×${F(a.width)}=${F(a.value)} units²`,`A′=10−2x=${F(a.slope)}; A″=−2`,S('Maximum area 25 units² at x=5. Drawing scaled 0.65×.','अधिकतम क्षेत्रफल 25 इकाई², x=5 पर। चित्र 0.65× मापित है।'))}
 else if(id==='aod-rate'){this.clear(false);this.circle([0,0],v);line([0,0],[v,0]);label([v/2,.4],'r');rows.push(`r=${F(v)} units; dr/dt=0.2 units/s`,`V=${F(a.volume)} units³; dV/dt=4π(${F(v)})²(0.2)=${F(a.value)} units³/s`,S('The circle is a cross-section of a sphere.','वृत्त गोले का अनुप्रस्थ काट है।'))}
 else if(id==='integral-family'||id==='de-initial'){curve(x=>x*x+v);mark([0,v],'C');rows.push(`y=x²+(${v}); dy/dx=2x`,S('Different constants give parallel vertical shifts, with the same derivative.','अलग अचर ऊर्ध्व विस्थापन देते हैं; अवकलज समान है।'))}
 else if(id==='integral-sum'){for(let i=1;i<=a.n;i++){let x=i*a.dx,y=x*x;path([[x-a.dx,0],[x,0],[x,y],[x-a.dx,y]],'shape',true)}curve(x=>x*x);rows.push(`R${a.n}=Σ (iΔx)²Δx=${F(a.value)}; Δx=2/${a.n}`,`∫₀²x²dx=8/3=${F(a.exact)}; ${S('error','त्रुटि')}=${F(a.error)}`)}
 else if(id==='integral-signed'){region(x=>x,()=>0,-v,0);region(x=>x,()=>0,0,v);curve(x=>x);rows.push(`∫₋ₐᵃ x dx=0; ∫₋ₐᵃ |x|dx=${F(a.area)} units²`,S('Negative signed contribution cancels positive; area never cancels.','ऋणात्मक सचिह्न योगदान धनात्मक को काटता है; क्षेत्रफल नहीं कटता।'))}
 else if(id==='area-parabola'){region(x=>x*x,()=>0,0,v);curve(x=>x*x);rows.push(`A=∫₀^${F(v)} x²dx=[x³/3]₀^${F(v)}=${F(a.value)} units²`)}
 else if(id==='area-circle'){region(x=>Math.sqrt(Math.max(0,v*v-x*x)),()=>0,-v,v);this.circle([0,0],v);rows.push(`A(semi)=∫₋ᵣʳ √(r²−x²)dx=π(${F(v)})²/2=${F(a.value)} units²`,`A(circle)=${F(a.full)} units²`)}
 else if(id==='area-between'){region(x=>v*x,x=>x*x,0,v);curve(x=>v*x,'gold');curve(x=>x*x);mark([v,v*v],'P');rows.push(`A=∫₀^${F(v)} (${F(v)}x−x²)dx=${F(a.value)} units²`,S('Gold line above green parabola between intersections.','प्रतिच्छेदों के बीच सुनहरी रेखा हरे परवलय के ऊपर है।'))}
 else if(id==='de-exponential'||id==='de-linear'){curve(a.f);mark([0,id==='de-exponential'?1:0],S('Initial','आरंभिक'));mark([1,a.value],'x=1');if(id==='de-linear')line([-8,v],[8,v],'axis',{'stroke-dasharray':'5 5'});rows.push(id==='de-exponential'?`y=e^(${F(v)}x); y′=${F(v)}y; y(0)=1`:`y=${F(v)}(1−e^(−x)); y′+y=${F(v)}; y(0)=0`,`y(1)=${F(a.value)}`)}
 else if(id==='vector-sum'){path([[0,0],a.a,a.result,a.b],'shape',true);vec([0,0],a.a,'a');vec(a.a,a.result,'b');vec([0,0],a.result,'a+b');rows.push(`a+b=(${F(a.result[0])},3); |a+b|=${F(a.value)}`)}
 else if(id==='vector-dot'||id==='vector-cross'){vec([0,0],[3,0],'a');vec([0,0],a.b,'b');if(id==='vector-dot'){mark(a.b.map(q=>q*a.projection/2),S('projection','प्रक्षेप'));rows.push(`a·b=6cos(${v}°)=${F(a.value)}`,S('Scalar projection of a on b','b पर a का अदिश प्रक्षेप')+`=${F(a.projection)}`)}else{path([[0,0],[3,0],[3+a.b[0],a.b[1]],a.b],'shape',true);label([-7,4],S(a.value>0?'⊙ +z out of screen':a.value<0?'⊗ −z into screen':'Zero cross product',a.value>0?'⊙ +z स्क्रीन से बाहर':a.value<0?'⊗ −z स्क्रीन के अंदर':'शून्य सदिश गुणन'));rows.push(`a×b=(0,0,${F(a.value)}); |a×b|=${F(a.magnitude)}`,`Area=${F(a.magnitude)} units²`)}}
 else if(id.startsWith('space-')){const P=spatial();heading('Oblique projection: screen angles are not spatial angles','तिर्यक प्रक्षेप: स्क्रीन के कोण स्थानिक कोण नहीं');if(id==='space-line'){line(P([-1,-3,-1]),P([3,5,3]));mark(P(a.point),'P');rows.push(`P=(${a.point.map(F).join(', ')})`,`(l,m,n)=(${a.cosines.map(F).join(', ')}); l²+m²+n²=1`)}else if(id==='space-angle'){vec([0,0],P([4,0,0]),'a');vec([0,0],P(a.b.map(q=>q*4)),'b');rows.push(`cos φ=|cos(${v}°)|; φ=${F(a.value)}°`,S('Unoriented lines use the smaller angle.','अदिशित रेखाओं के लिए छोटा कोण लें।'))}else{line(P([-5,0,0]),P([5,0,0]));line(P([0,-4,v]),P([0,4,v]),'gold');gold(P([0,0,0]),P([0,0,v]));mark(P([0,0,v]),'H');rows.push(`d=|(a₂−a₁)·(b₁×b₂)|/|b₁×b₂|=|${F(v)}|=${F(a.value)} units`,S(a.intersect?'Intersecting: d=0':'Skew: no intersection',a.intersect?'प्रतिच्छेदी: d=0':'विषमतलीय: प्रतिच्छेद नहीं'))}}
 else if(id.startsWith('lp-')){this.scale=22;this.cx=135;this.cy=310;this.clear(false);for(let j=0;j<=9;j++){line([j,0],[j,9],'grid');line([0,j],[9,j],'grid');if(j&&j%2===0){label([j,-.5],j);label([-.6,j],j)}}line([0,0],[9,0],'axis');line([0,0],[0,9],'axis');label([9,-.7],S('X-axis','X-अक्ष'));label([.2,9.4],S('Y-axis','Y-अक्ष'));if(id==='lp-unbounded'){path([[v,0],[9,0],[9,9],[0,9],[0,v]],'shape',true);this.equation(1,1,-v);vec([4,4],[6,6],S('continues','आगे जारी'));rows.push(`Min Z=${v} ${S('on segment','रेखाखंड पर')} (0,${v})—(${v},0)`,S('No finite maximum; clipped drawing is not a bound.','परिमित अधिकतम नहीं; कटा चित्र सीमा नहीं है।'))}else{path(a.vertices,'shape',true);a.vertices.forEach((p,i)=>mark(p,id==='lp-corners'?String(a.z[i]):`(${p})`));if(id==='lp-corners'){this.equation(v,2,-a.best,'gold');a.optimal.forEach(p=>mark(p,'★'));rows.push(`Max Z=${F(a.best)}; ${S('optimal vertices','इष्टतम शीर्ष')}: ${a.optimal.map(p=>'('+p+')').join(', ')}`,v===2?S('Every point on the optimal edge x+y=6 is also optimal.','इष्टतम किनारे x+y=6 का हर बिंदु भी इष्टतम है।'):S('Compare all feasible vertices, not just intercepts.','सभी सुसंगत शीर्ष मिलाएँ, केवल अंतःखंड नहीं।'))}else{mark(a.point,'★');rows.push(`Max Z=3(${v})+2(0)=${a.value}`,S('Optimum at','इष्टतम')+` (${v},0)`)}}}
 else if(id==='prob-conditional'){this.clear(false);for(let k=1;k<=6;k++){let p=[-6+(k-1)*2.3,0];this.circle(p,.65,k<=v?'gold':'shape',{fill:k<=v?'#f3c57322':'none'});label([p[0]-.15,.15],k);label([p[0]-.5,-1],k%2===0?'A':'A′')}rows.push(`P(A|B)=${a.favourable}/${v}=${F(a.value)}; P(A)=1/2`,S('A and B independent','A तथा B स्वतंत्र')+': '+S(a.independent?'Yes':'No',a.independent?'हाँ':'नहीं'))}
 else if(id==='prob-total'||id==='prob-bayes'){this.clear(false);const O=[-7,0],U=[-2,2],D=[-2,-2];line(O,U);line(O,D);label([-6,2],`p=${F(v)}`);label([-6,-2],`1−p=${F(1-v)}`);mark(U,S('Box1','डिब्बा1'));mark(D,S('Box2','डिब्बा2'));for(let [p,prob,leaf]of[[U,.8,[4,3.8]],[D,.3,[4,-.2]]]){gold(p,leaf);line(p,[4,p[1]-1.5]);label([0,p[1]+.8],`P(R|B)=${prob}`);mark(leaf,S('Red','लाल'));label([4,p[1]-1.7],S('Not red','लाल नहीं'))}rows.push(`P(R)=0.8(${F(v)})+0.3(${F(1-v)})=${F(id==='prob-total'?a.value:a.total)}`);if(id==='prob-bayes')rows.push(`P(B1|R)=0.8(${F(v)})/${F(a.total)}=${F(a.value)}`);else rows.push(S('Sum the disjoint red paths.','असंयुक्त लाल पथों को जोड़ें।'))}
 this.report(rows);this.svg.dataset.value=String(a.value);this.svg.dataset.changed=String(this.changed)
 }
}
